const items = $input.all();

function parseJSON(valor) {
  if (typeof valor !== "string") {
    return valor;
  }

  return JSON.parse(valor);
}

const resultado = [];

for (const item of items) {

  // O JSON chega como texto no campo "input"
  const dados = parseJSON(item.json.input ?? item.json);

  // Aceita um array ou um objeto individual
  const registros = Array.isArray(dados) ? dados : [dados];

  for (const registro of registros) {

    if (
      registro.essayOutput == null ||
      registro.headlineOutput == null
    ) {
      continue;
    }

    resultado.push({
      json: {
        essayOutput: parseJSON(registro.essayOutput),
        headlineOutput: parseJSON(registro.headlineOutput)
      }
    });

  }
}

return resultado;
